CREATE TABLE IF NOT EXISTS crm_opportunities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid NOT NULL REFERENCES crm_leads(id) ON DELETE CASCADE, stage text NOT NULL DEFAULT 'qualified', value_minor bigint NOT NULL DEFAULT 0, currency text NOT NULL DEFAULT 'NGN', owner_id uuid, next_follow_up_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());